import React from 'react';
import {
  AbsoluteFill,
  Audio,
  Img,
  Sequence,
  interpolate,
  spring,
  staticFile,
  useCurrentFrame,
  useVideoConfig,
} from 'remotion';

export type AnimeShortProps = {
  /** SEO title for the day's video — shown on the opening title card. */
  title: string;
  /** Full voiceover script (plain text). Split into caption chunks automatically. */
  scriptText: string;
  /** MP3 file name inside the Remotion public/ folder (generated by edge-tts). */
  audioFile: string;
  /**
   * Scene image file names inside public/scenes/ (e.g. ["scene-1.jpg", ...]),
   * generated by scripts/make-images.py from the day's scene prompts.
   * Empty array → v1 animated-gradient fallback (no images needed).
   */
  scenes: string[];
};

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/** Split the script into short caption chunks of ~wordsPerChunk words each. */
export function chunkScript(scriptText: string, wordsPerChunk = 4): string[] {
  const words = scriptText.replace(/\s+/g, ' ').trim().split(' ').filter(Boolean);
  const chunks: string[] = [];
  for (let i = 0; i < words.length; i += wordsPerChunk) {
    chunks.push(words.slice(i, i + wordsPerChunk).join(' '));
  }
  return chunks.length > 0 ? chunks : [''];
}

/** Deterministic pseudo-random from a seed (stable across renders). */
const rand = (seed: number) => {
  const x = Math.sin(seed * 9973.13) * 43758.5453;
  return x - Math.floor(x);
};

/* ------------------------------------------------------------------ */
/* v2: full-screen AI scene images with Ken Burns motion               */
/* ------------------------------------------------------------------ */

const CROSSFADE_FRAMES = 12;

const SceneImages: React.FC<{scenes: string[]}> = ({scenes}) => {
  const frame = useCurrentFrame();
  const {durationInFrames} = useVideoConfig();
  const count = scenes.length;
  if (count === 0) return null;
  const framesPerScene = durationInFrames / count;

  return (
    <AbsoluteFill style={{backgroundColor: '#000'}}>
      {scenes.map((file, i) => {
        const start = i * framesPerScene;
        const end = start + framesPerScene;
        const isLast = i === count - 1;
        // A scene is visible from just before its slot (crossfade-in) until
        // just after it (the next scene fades in on top of it).
        const visibleFrom = i === 0 ? 0 : start - CROSSFADE_FRAMES;
        const visibleUntil = isLast ? durationInFrames : end + CROSSFADE_FRAMES;
        if (frame < visibleFrom || frame >= visibleUntil) return null;

        const opacity =
          i === 0
            ? 1
            : interpolate(frame, [start - CROSSFADE_FRAMES, start + CROSSFADE_FRAMES], [0, 1], {
                extrapolateLeft: 'clamp',
                extrapolateRight: 'clamp',
              });

        // Ken Burns: progress across this scene's own slot; even scenes zoom
        // in, odd scenes zoom out, with a gentle alternating pan.
        const progress = interpolate(frame, [start, end], [0, 1], {
          extrapolateLeft: 'clamp',
          extrapolateRight: 'clamp',
        });
        const zoomIn = i % 2 === 0;
        const scale = zoomIn
          ? interpolate(progress, [0, 1], [1.02, 1.14])
          : interpolate(progress, [0, 1], [1.14, 1.02]);
        const panX = (i % 2 === 0 ? 1 : -1) * interpolate(progress, [0, 1], [-1.6, 1.6]);
        const panY = interpolate(progress, [0, 1], [1.2, -1.2]);

        return (
          <AbsoluteFill key={`${file}-${i}`} style={{opacity, overflow: 'hidden'}}>
            <Img
              src={staticFile(`scenes/${file}`)}
              style={{
                width: '100%',
                height: '100%',
                objectFit: 'cover',
                transform: `scale(${scale}) translate(${panX}%, ${panY}%)`,
              }}
            />
          </AbsoluteFill>
        );
      })}
      {/* subtle vignette to sit captions/title over busy artwork */}
      <AbsoluteFill
        style={{background: 'radial-gradient(ellipse at center, transparent 52%, rgba(0,0,0,0.5) 100%)'}}
      />
    </AbsoluteFill>
  );
};

/* ------------------------------------------------------------------ */
/* v1 fallback: animated gradient scenes (used when scenes is empty)   */
/* ------------------------------------------------------------------ */

const PALETTES: Array<[string, string, string]> = [
  ['#1b1035', '#4c1d95', '#db2777'],
  ['#0b1e3a', '#155e75', '#0ea5e9'],
  ['#2a0a12', '#7f1d1d', '#f59e0b'],
  ['#0a2418', '#065f46', '#34d399'],
  ['#241033', '#6d28d9', '#38bdf8'],
  ['#331505', '#92400e', '#ef4444'],
];

const SCENE_SECONDS = 9;

const GradientScenes: React.FC = () => {
  const frame = useCurrentFrame();
  const {fps, width, height} = useVideoConfig();
  const t = frame / fps;
  const sceneFloat = t / SCENE_SECONDS;
  const sceneIndex = Math.floor(sceneFloat);
  const blend = Math.min(1, (sceneFloat - sceneIndex) / 0.12); // quick crossfade at scene start

  const renderScene = (idx: number, opacity: number) => {
    const [c1, c2, c3] = PALETTES[idx % PALETTES.length];
    // Slow drift so the gradient itself feels alive.
    const drift = interpolate(frame, [0, fps * 60], [0, 140], {extrapolateRight: 'extend'});
    const blob = (i: number) => {
      const speed = 0.11 + rand(idx * 7 + i) * 0.12;
      const cx = 50 + 42 * Math.sin(t * speed + idx * 2.1 + i * 2.4);
      const cy = 50 + 42 * Math.cos(t * speed * 0.9 + idx * 1.3 + i * 1.7);
      const size = (34 + rand(idx * 13 + i * 3) * 30) * (width / 100);
      const col = [c2, c3, c2][i % 3];
      return (
        <div
          key={i}
          style={{
            position: 'absolute',
            left: (cx / 100) * width - size / 2,
            top: (cy / 100) * height - size / 2,
            width: size,
            height: size,
            borderRadius: '50%',
            background: `radial-gradient(circle, ${col}cc 0%, transparent 70%)`,
            filter: 'blur(30px)',
          }}
        />
      );
    };
    return (
      <AbsoluteFill style={{opacity, backgroundColor: c1}}>
        <AbsoluteFill
          style={{
            background: `linear-gradient(${150 + drift}deg, ${c1} 0%, ${c2} 58%, ${c1} 100%)`,
          }}
        />
        {[0, 1, 2].map(blob)}
        {/* subtle vignette */}
        <AbsoluteFill
          style={{background: 'radial-gradient(ellipse at center, transparent 55%, rgba(0,0,0,0.5) 100%)'}}
        />
      </AbsoluteFill>
    );
  };

  return (
    <AbsoluteFill>
      {renderScene(sceneIndex, 1)}
      {blend < 1 ? renderScene(sceneIndex + 1, blend) : null}
    </AbsoluteFill>
  );
};

/* ------------------------------------------------------------------ */
/* Shared layers                                                       */
/* ------------------------------------------------------------------ */

const TITLE_CARD_SECONDS = 2.5;

const TitleCard: React.FC<{title: string}> = ({title}) => {
  const frame = useCurrentFrame();
  const {fps, width} = useVideoConfig();
  const dur = Math.round(TITLE_CARD_SECONDS * fps);
  const inPop = spring({frame, fps, config: {damping: 16, stiffness: 120}});
  const outOpacity = interpolate(frame, [dur - 12, dur], [1, 0], {
    extrapolateLeft: 'clamp',
    extrapolateRight: 'clamp',
  });
  return (
    <AbsoluteFill
      style={{
        justifyContent: 'center',
        alignItems: 'center',
        padding: width * 0.07,
        opacity: outOpacity,
        // Dark overlay so the title stays readable over the first scene image.
        background: 'rgba(0,0,0,0.48)',
      }}
    >
      <div
        style={{
          transform: `scale(${0.85 + inPop * 0.15})`,
          background: 'rgba(0,0,0,0.55)',
          border: '2px solid rgba(255,255,255,0.25)',
          borderRadius: 28,
          padding: `${width * 0.05}px ${width * 0.045}px`,
          textAlign: 'center',
        }}
      >
        <div
          style={{
            color: '#fbbf24',
            fontFamily: 'Arial, "DejaVu Sans", sans-serif',
            fontWeight: 800,
            letterSpacing: 4,
            fontSize: width * 0.032,
            marginBottom: 18,
          }}
        >
          DYNOSHI • ANIME HINDI
        </div>
        <div
          style={{
            color: 'white',
            fontFamily: 'Arial, "DejaVu Sans", sans-serif',
            fontWeight: 900,
            fontSize: width * 0.062,
            lineHeight: 1.25,
          }}
        >
          {title}
        </div>
      </div>
    </AbsoluteFill>
  );
};

const Captions: React.FC<{chunks: string[]}> = ({chunks}) => {
  const frame = useCurrentFrame();
  const {fps, width, durationInFrames} = useVideoConfig();

  // Caption timing: chunks distributed across the full duration in
  // proportion to their word counts (speech rate is roughly uniform).
  const counts = chunks.map((c) => c.split(' ').length);
  const total = counts.reduce((a, b) => a + b, 0) || 1;
  let acc = 0;
  const ranges = counts.map((n) => {
    const from = Math.round((acc / total) * durationInFrames);
    acc += n;
    const to = Math.round((acc / total) * durationInFrames);
    return {from, to};
  });
  const activeIdx = ranges.findIndex((r) => frame >= r.from && frame < r.to);
  if (activeIdx < 0) return null;
  const {from, to} = ranges[activeIdx];
  const pop = spring({frame: frame - from, fps, config: {damping: 18, stiffness: 200}});

  // Karaoke-style active word inside the chunk: words are assumed to be
  // spoken at a uniform rate within the chunk's frame range.
  const words = chunks[activeIdx].split(' ');
  const chunkSpan = Math.max(1, to - from);
  const activeWord = Math.min(
    words.length - 1,
    Math.floor(((frame - from) / chunkSpan) * words.length),
  );

  const outline =
    '2px 0 0 #000, -2px 0 0 #000, 0 2px 0 #000, 0 -2px 0 #000, 2px 2px 0 #000, -2px -2px 0 #000, 0 4px 14px rgba(0,0,0,0.9)';

  return (
    <div
      style={{
        position: 'absolute',
        left: 0,
        right: 0,
        bottom: '16%',
        display: 'flex',
        justifyContent: 'center',
        padding: `0 ${width * 0.06}px`,
      }}
    >
      <div
        style={{
          transform: `scale(${0.92 + pop * 0.08})`,
          background: 'rgba(0,0,0,0.55)',
          borderRadius: 20,
          padding: `${width * 0.028}px ${width * 0.04}px`,
          maxWidth: '100%',
        }}
      >
        <div
          style={{
            color: 'white',
            fontFamily: 'Arial, "DejaVu Sans", sans-serif',
            fontWeight: 800,
            fontSize: width * 0.058,
            lineHeight: 1.35,
            textAlign: 'center',
            textShadow: outline,
          }}
        >
          {words.map((word, wi) => (
            <React.Fragment key={wi}>
              {wi > 0 ? ' ' : ''}
              {wi === activeWord ? (
                <span
                  style={{
                    background: '#facc15',
                    color: '#000',
                    borderRadius: 10,
                    padding: '0 12px',
                    textShadow: 'none',
                  }}
                >
                  {word}
                </span>
              ) : (
                word
              )}
            </React.Fragment>
          ))}
        </div>
      </div>
    </div>
  );
};

const ProgressBar: React.FC = () => {
  const frame = useCurrentFrame();
  const {durationInFrames} = useVideoConfig();
  const pct = Math.min(100, (frame / Math.max(1, durationInFrames)) * 100);
  return (
    <div style={{position: 'absolute', left: 0, right: 0, bottom: 0, height: 12, background: 'rgba(255,255,255,0.15)'}}>
      <div
        style={{
          height: '100%',
          width: `${pct}%`,
          background: 'linear-gradient(90deg, #f59e0b, #ef4444, #db2777)',
        }}
      />
    </div>
  );
};

const Watermark: React.FC = () => {
  const {width} = useVideoConfig();
  return (
    <div
      style={{
        position: 'absolute',
        top: width * 0.045,
        left: 0,
        right: 0,
        textAlign: 'center',
        color: 'rgba(255,255,255,0.85)',
        fontFamily: 'Arial, "DejaVu Sans", sans-serif',
        fontWeight: 800,
        letterSpacing: 6,
        fontSize: width * 0.034,
        textShadow: '0 2px 8px rgba(0,0,0,0.7)',
      }}
    >
      DYNOSHI
    </div>
  );
};

/* ------------------------------------------------------------------ */
/* Composition                                                         */
/* ------------------------------------------------------------------ */

export const AnimeShort: React.FC<AnimeShortProps> = ({title, scriptText, audioFile, scenes}) => {
  const {fps} = useVideoConfig();
  const chunks = chunkScript(scriptText, 4);
  const hasScenes = Array.isArray(scenes) && scenes.length > 0;
  return (
    <AbsoluteFill style={{backgroundColor: '#000'}}>
      <Audio src={staticFile(audioFile)} />
      {hasScenes ? <SceneImages scenes={scenes} /> : <GradientScenes />}
      <Watermark />
      <Captions chunks={chunks} />
      {/* Title card overlays the first ~2.5 seconds while the voiceover starts. */}
      <Sequence from={0} durationInFrames={Math.round(TITLE_CARD_SECONDS * fps)}>
        <TitleCard title={title} />
      </Sequence>
      <ProgressBar />
    </AbsoluteFill>
  );
};
